public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Normalize strings: replace null with empty string
    List<String> normalized = new ArrayList<>();
    for (String s : strings) {
        normalized.add(s == null ? "" : s);
    }
    // If any string is empty, only possible substring length is 0
    for (String s : normalized) {
        if (s.isEmpty()) {
            return 0;
        }
    }
    String first = normalized.get(0);
    int maxLen = first.length();
    // Iterate lengths from maxLen down to 1
    for (int len = maxLen; len >= 1; len--) {
        // Generate all substrings of first string of this length
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            substrings.add(first.substring(i, i + len));
        }
        // Check each candidate
        for (String candidate : substrings) {
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String t : normalized) {
                if (!(t.contains(candidate) || t.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

