public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long current = 1;
    int count = 0;
    while (count < n) {
        result.add((int) current);
        count++;
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

